<script setup lang="ts">
import type { AcademicAdministrationWorkspace } from '~/server/types/academic-administration'

definePageMeta({ middleware: 'auth' })
useHead({ title: 'Master Data Akademik' })
type Tab = 'program' | 'period' | 'course' | 'curriculum' | 'calendar'
const { $api } = useNuxtApp()
const data = ref<AcademicAdministrationWorkspace | null>(null)
const tab = ref<Tab>('program')
const loading = ref(true), working = ref(false), errorMessage = ref(''), noticeMessage = ref('')
const program = reactive({ id: '', facultyId: '', code: '', name: '', level: 'S1', active: true, accreditationStatus: '', accreditationExpiresAt: '', expectedVersion: 0 })
const period = reactive({ id: '', academicYear: '', term: 'ODD', startsAt: '', endsAt: '', krsOpensAt: '', krsClosesAt: '', krsRevisionClosesAt: '', krsStatus: 'DRAFT', active: true, expectedVersion: 0 })
const course = reactive({ courseId: '', code: '', name: '', programStudyId: '', credits: 3, semesterRecommendation: 1, prerequisiteCourseCodes: '', equivalentCourseCodes: '', status: 'DRAFT', expectedCurrentVersion: 0 })
const curriculum = reactive({ curriculumId: '', programStudyId: '', name: '', effectiveCohortFrom: new Date().getFullYear(), effectiveCohortTo: new Date().getFullYear() + 4, courseVersionIds: '', status: 'DRAFT', expectedCurrentVersion: 0 })
const calendar = reactive({ id: '', periodId: '', programStudyIds: '', title: '', category: 'ACADEMIC', startsAt: '', endsAt: '', description: '', expectedVersion: 0 })
const tabs: Array<{ id: Tab; label: string; icon: string }> = [{ id: 'program', label: 'Program studi', icon: 'uil-building' }, { id: 'period', label: 'Periode', icon: 'uil-calendar-alt' }, { id: 'course', label: 'Mata kuliah', icon: 'uil-book-alt' }, { id: 'curriculum', label: 'Kurikulum', icon: 'uil-books' }, { id: 'calendar', label: 'Kalender', icon: 'uil-schedule' }]
const key = (purpose: string) => `${purpose}-${globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`}`
const iso = (value: string) => new Date(/[zZ]|[+-]\d{2}:\d{2}$/.test(value) ? value : `${value}+07:00`).toISOString()
const list = (value: string) => [...new Set(value.split(/[\s,]+/).filter(Boolean))]
const errorText = (error: unknown) => { const value = error as { response?: { data?: { statusMessage?: string; message?: string } }; message?: string }; return value.response?.data?.statusMessage || value.response?.data?.message || value.message || 'Master data tidak dapat disimpan.' }

const load = async () => { loading.value = true; try { data.value = (await $api.get<AcademicAdministrationWorkspace>('/academic/administration')).data; const firstProgram = data.value.programs.find(item => item.active)?.id || ''; const firstPeriod = data.value.periods.find(item => item.active)?.id || ''; if (!course.programStudyId) course.programStudyId = firstProgram; if (!curriculum.programStudyId) curriculum.programStudyId = firstProgram; if (!calendar.programStudyIds) calendar.programStudyIds = firstProgram; if (!calendar.periodId) calendar.periodId = firstPeriod } catch (error) { errorMessage.value = errorText(error) } finally { loading.value = false } }
const run = async (path: string, body: Record<string, unknown>, message: string) => { working.value = true; errorMessage.value = ''; noticeMessage.value = ''; try { await $api.post(path, body, { headers: { 'Idempotency-Key': key(`academic-master-${tab.value}`) } }); noticeMessage.value = message; await load() } catch (error) { errorMessage.value = errorText(error) } finally { working.value = false } }
const saveProgram = () => run('/academic/master/programs', { ...program }, 'Program studi dan status akreditasi berhasil disimpan.')
const savePeriod = () => run('/academic/master/periods', { ...period, startsAt: iso(period.startsAt), endsAt: iso(period.endsAt), krsOpensAt: iso(period.krsOpensAt), krsClosesAt: iso(period.krsClosesAt), krsRevisionClosesAt: iso(period.krsRevisionClosesAt) }, 'Periode dan kebijakan KRS berhasil disimpan.')
const saveCourse = () => run('/academic/master/courses', { ...course, credits: Number(course.credits), semesterRecommendation: Number(course.semesterRecommendation), prerequisiteCourseCodes: list(course.prerequisiteCourseCodes), equivalentCourseCodes: list(course.equivalentCourseCodes) }, 'Versi mata kuliah imutabel berhasil dibuat.')
const saveCurriculum = () => run('/academic/master/curricula', { ...curriculum, effectiveCohortFrom: Number(curriculum.effectiveCohortFrom), effectiveCohortTo: Number(curriculum.effectiveCohortTo), courseVersionIds: list(curriculum.courseVersionIds) }, 'Versi kurikulum imutabel berhasil dibuat.')
const saveCalendar = () => run('/academic/master/calendar', { ...calendar, programStudyIds: list(calendar.programStudyIds), startsAt: iso(calendar.startsAt), endsAt: iso(calendar.endsAt), description: calendar.description || undefined }, 'Agenda akademik berhasil disimpan.')
const selectProgram = (id: string) => { const item = data.value?.programs.find(entry => entry.id === id); if (item) Object.assign(program, item, { expectedVersion: item.version }) }
const selectPeriod = (id: string) => { const item = data.value?.periods.find(entry => entry.id === id); if (item) Object.assign(period, item, { startsAt: item.startsAt.slice(0, 16), endsAt: item.endsAt.slice(0, 16), krsOpensAt: item.krsOpensAt.slice(0, 16), krsClosesAt: item.krsClosesAt.slice(0, 16), krsRevisionClosesAt: (item.krsRevisionClosesAt || item.endsAt).slice(0, 16), krsStatus: item.krsStatus || 'DRAFT', expectedVersion: item.version }) }
onMounted(load)
</script>

<template>
  <div class="page-stack master-page">
    <AppPageHeader eyebrow="Administrasi akademik" title="Master data akademik" description="Kelola program studi, periode akademik, mata kuliah, kurikulum, dan kalender kampus."><template #actions><NuxtLink class="btn btn-outline-secondary" to="/akademik/administrasi"><i class="uil uil-arrow-left me-2" />Kembali</NuxtLink><button class="btn btn-primary" :disabled="loading" @click="load"><i class="uil uil-refresh me-2" />Muat ulang</button></template></AppPageHeader>
    <div v-if="noticeMessage" class="alert alert-success">{{ noticeMessage }}</div><div v-if="errorMessage" class="alert alert-danger">{{ errorMessage }}</div><div v-if="loading" class="alert alert-info">Memuat master data...</div>
    <nav class="master-tabs"><button v-for="item in tabs" :key="item.id" :class="{ active: tab === item.id }" @click="tab = item.id"><i class="uil" :class="item.icon" />{{ item.label }}</button></nav>
    <div v-if="data" class="master-layout">
      <section class="surface-card form-card">
        <template v-if="tab === 'program'"><header><span>Mutable dengan versi</span><h2>Program studi</h2><p>Perubahan memerlukan versi terkini agar pembaruan tidak saling menimpa.</p></header><form @submit.prevent="saveProgram"><label>Data tersedia<select class="form-select" @change="selectProgram(($event.target as HTMLSelectElement).value)"><option value="">Pilih untuk sunting</option><option v-for="item in data.programs" :key="item.id" :value="item.id">{{ item.code }} · {{ item.name }} (v{{ item.version }})</option></select></label><div class="form-row"><label>ID<input v-model="program.id" class="form-control" required></label><label>Fakultas<input v-model="program.facultyId" class="form-control" required></label></div><div class="form-row"><label>Kode<input v-model="program.code" class="form-control" required></label><label>Jenjang<select v-model="program.level" class="form-select"><option>D3</option><option>S1</option><option>S2</option></select></label></div><label>Nama<input v-model="program.name" class="form-control" required></label><div class="form-row"><label>Akreditasi<input v-model="program.accreditationStatus" class="form-control" required></label><label>Berlaku sampai<input v-model="program.accreditationExpiresAt" type="date" class="form-control" required></label></div><label class="check"><input v-model="program.active" type="checkbox"> Program aktif</label><button class="btn btn-primary" :disabled="working">Simpan program v{{ program.expectedVersion + 1 }}</button></form></template>
        <template v-else-if="tab === 'period'">
          <header><span>Kalender inti</span><h2>Periode akademik &amp; KRS</h2><p>Satu perubahan memperbarui definisi semester dan kebijakan KRS yang dibaca mahasiswa.</p></header>
          <form @submit.prevent="savePeriod">
            <label>Data tersedia<select class="form-select" @change="selectPeriod(($event.target as HTMLSelectElement).value)"><option value="">Buat periode baru</option><option v-for="item in data.periods" :key="item.id" :value="item.id">{{ item.academicYear }} · {{ item.term }} (v{{ item.version }})</option></select></label>
            <div class="form-row"><label>ID<input v-model="period.id" class="form-control" required></label><label>Tahun akademik<input v-model="period.academicYear" class="form-control" required></label></div>
            <label>Term<select v-model="period.term" class="form-select"><option value="ODD">Gasal</option><option value="EVEN">Genap</option><option value="SHORT">Pendek</option></select></label>
            <div class="form-row"><label>Mulai semester<input v-model="period.startsAt" type="datetime-local" class="form-control" required></label><label>Selesai semester<input v-model="period.endsAt" type="datetime-local" class="form-control" required></label></div>
            <div class="form-row"><label>KRS dibuka<input v-model="period.krsOpensAt" type="datetime-local" class="form-control" required></label><label>KRS ditutup<input v-model="period.krsClosesAt" type="datetime-local" class="form-control" required></label></div>
            <div class="form-row"><label>Revisi KRS ditutup<input v-model="period.krsRevisionClosesAt" type="datetime-local" class="form-control" required></label><label>Status KRS<select v-model="period.krsStatus" class="form-select"><option value="DRAFT">Draf</option><option value="KRS_OPEN">Dibuka</option><option value="KRS_CLOSED">Pengisian ditutup</option><option value="CLOSED">Periode ditutup</option></select></label></div>
            <label class="check"><input v-model="period.active" type="checkbox"> Periode aktif</label><button class="btn btn-primary" :disabled="working">Simpan periode dan kebijakan KRS</button>
          </form>
        </template>
        <template v-else-if="tab === 'course'"><header><span>Snapshot imutabel</span><h2>Versi mata kuliah</h2></header><form @submit.prevent="saveCourse"><div class="form-row"><label>ID mata kuliah<input v-model="course.courseId" class="form-control" required></label><label>Kode<input v-model="course.code" class="form-control" required></label></div><label>Nama<input v-model="course.name" class="form-control" required></label><label>Program<select v-model="course.programStudyId" class="form-select"><option v-for="item in data.programs" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div class="form-row"><label>SKS<input v-model.number="course.credits" type="number" min="1" max="12" class="form-control"></label><label>Rekomendasi semester<input v-model.number="course.semesterRecommendation" type="number" min="1" max="14" class="form-control"></label></div><label>Prasyarat <small>kode dipisah koma</small><input v-model="course.prerequisiteCourseCodes" class="form-control"></label><label>Ekuivalensi <small>kode dipisah koma</small><input v-model="course.equivalentCourseCodes" class="form-control"></label><div class="form-row"><label>Status<select v-model="course.status" class="form-select"><option>DRAFT</option><option>ACTIVE</option><option>RETIRED</option></select></label><label>Versi saat ini<input v-model.number="course.expectedCurrentVersion" type="number" min="0" class="form-control"></label></div><button class="btn btn-primary" :disabled="working">Buat versi berikutnya</button></form></template>
        <template v-else-if="tab === 'curriculum'"><header><span>Snapshot imutabel</span><h2>Versi kurikulum</h2></header><form @submit.prevent="saveCurriculum"><label>ID kurikulum<input v-model="curriculum.curriculumId" class="form-control" required></label><label>Nama<input v-model="curriculum.name" class="form-control" required></label><label>Program<select v-model="curriculum.programStudyId" class="form-select"><option v-for="item in data.programs" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><div class="form-row"><label>Angkatan mulai<input v-model.number="curriculum.effectiveCohortFrom" type="number" class="form-control"></label><label>Angkatan akhir<input v-model.number="curriculum.effectiveCohortTo" type="number" class="form-control"></label></div><label>ID versi mata kuliah <small>pisahkan koma</small><textarea v-model="curriculum.courseVersionIds" class="form-control" rows="4" required /></label><div class="form-row"><label>Status<select v-model="curriculum.status" class="form-select"><option>DRAFT</option><option>ACTIVE</option><option>RETIRED</option></select></label><label>Versi saat ini<input v-model.number="curriculum.expectedCurrentVersion" type="number" min="0" class="form-control"></label></div><button class="btn btn-primary" :disabled="working">Buat versi kurikulum</button></form></template>
        <template v-else><header><span>Agenda dan deadline</span><h2>Kalender akademik</h2></header><form @submit.prevent="saveCalendar"><div class="form-row"><label>ID agenda<input v-model="calendar.id" class="form-control" required></label><label>Periode<select v-model="calendar.periodId" class="form-select"><option v-for="item in data.periods" :key="item.id" :value="item.id">{{ item.academicYear }} · {{ item.term }}</option></select></label></div><label>Judul<input v-model="calendar.title" class="form-control" required></label><div class="form-row"><label>Kategori<select v-model="calendar.category" class="form-select"><option>ACADEMIC</option><option>KRS</option><option>EXAM</option><option>GRADUATION</option><option>HOLIDAY</option><option>DEADLINE</option></select></label><label>Program studi <small>pisahkan koma</small><input v-model="calendar.programStudyIds" class="form-control"></label></div><div class="form-row"><label>Mulai<input v-model="calendar.startsAt" type="datetime-local" class="form-control" required></label><label>Selesai<input v-model="calendar.endsAt" type="datetime-local" class="form-control" required></label></div><label>Deskripsi<textarea v-model="calendar.description" class="form-control" rows="3" /></label><label>Versi saat ini<input v-model.number="calendar.expectedVersion" type="number" min="0" class="form-control"></label><button class="btn btn-primary" :disabled="working">Simpan agenda</button></form></template>
      </section>
      <section class="surface-card inventory"><header><span>Inventaris aktif</span><h2>{{ tabs.find(item => item.id === tab)?.label }}</h2></header><template v-if="tab === 'program'"><article v-for="item in data.programs" :key="item.id"><strong>{{ item.code }} · {{ item.name }}</strong><small>{{ item.level }} · {{ item.accreditationStatus }} · v{{ item.version }}</small></article></template><template v-else-if="tab === 'period'"><article v-for="item in data.periods" :key="item.id"><strong>{{ item.academicYear }} · {{ item.term }}</strong><small>{{ item.id }} · {{ item.krsStatus || 'DRAFT' }} · v{{ item.version }}</small></article></template><template v-else-if="tab === 'course'"><article v-for="item in data.courses" :key="item.id"><strong>{{ item.code }} · {{ item.name }}</strong><small>{{ item.credits }} SKS · v{{ item.version }} · {{ item.status }}</small></article></template><template v-else-if="tab === 'curriculum'"><article v-for="item in data.curricula" :key="item.id"><strong>{{ item.name }}</strong><small>{{ item.totalCredits }} SKS · v{{ item.version }} · {{ item.status }}</small></article></template><template v-else><article v-for="item in data.calendar" :key="item.id"><strong>{{ item.title }}</strong><small>{{ item.category }} · {{ item.startsAt.slice(0,10) }} · v{{ item.version }}</small></article></template></section>
    </div>
  </div>
</template>

<style scoped>
.master-page{display:grid;gap:1rem}.master-tabs{display:flex;gap:.35rem;overflow:auto;padding:.35rem;border:1px solid var(--campus-border);border-radius:.8rem;background:#fff}.master-tabs button{display:flex;min-width:125px;flex:1;align-items:center;justify-content:center;gap:.4rem;padding:.55rem;border:0;border-radius:.55rem;color:#6f827a;background:transparent;font-size:.62rem;font-weight:750}.master-tabs button.active{color:#fff;background:var(--campus-forest-700)}.master-layout{display:grid;grid-template-columns:minmax(360px,.85fr) minmax(0,1.15fr);gap:1rem;align-items:start}.surface-card{padding:1rem}.surface-card>header{margin-bottom:.8rem}.surface-card>header span{color:#a87a20;font-size:.52rem;font-weight:800;text-transform:uppercase}.surface-card h2{margin:.12rem 0;color:#315348;font-size:.9rem}.surface-card header p{margin:0;color:#7b8b85;font-size:.56rem}.form-card form{display:grid;gap:.65rem}.form-card label{display:grid;gap:.25rem;color:#5f746b;font-size:.57rem;font-weight:700}.form-card label small{color:#84928c;font-weight:400}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:.5rem}.form-control,.form-select{font-size:.67rem}.check{display:flex!important;grid-template-columns:auto 1fr!important;align-items:center}.inventory article{display:flex;justify-content:space-between;gap:.7rem;padding:.65rem 0;border-top:1px solid var(--campus-border)}.inventory strong{color:#3c5d51;font-size:.62rem}.inventory small{color:#84928c;font-size:.52rem;text-align:right}@media(max-width:900px){.master-layout{grid-template-columns:1fr}}@media(max-width:600px){.form-row{grid-template-columns:1fr}.inventory article{align-items:flex-start;flex-direction:column}.inventory small{text-align:left}}
</style>
